//! Checked integer arithmetic for settlement amounts.
//!
//! Every product is formed in a wider integer (256 or 512 bits) before the division, so no
//! intermediate result can overflow silently. Every function returns a [`MathError`] instead of
//! panicking; callers choose the rounding direction explicitly so that rounding always favors the
//! pool.

use core::fmt;

pub use wide::{U256, U512};

// The lint fires inside the code generated by `construct_uint!`, not in this crate's code.
#[allow(clippy::manual_div_ceil)]
mod wide {
    uint::construct_uint! {
        /// Unsigned 256-bit integer used for `u128 * u128` intermediates.
        pub struct U256(4);
    }

    uint::construct_uint! {
        /// Unsigned 512-bit integer used for products of up to three `u128` factors.
        pub struct U512(8);
    }
}

/// Fixed-point one: fractions are stored as integers scaled by `1e18`.
pub const ONE: u128 = 1_000_000_000_000_000_000;

/// Arithmetic failure.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MathError {
    /// A divisor was zero.
    DivisionByZero,
    /// A result or an intermediate product does not fit its integer type.
    Overflow,
}

impl fmt::Display for MathError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::DivisionByZero => f.write_str("division by zero"),
            Self::Overflow => f.write_str("arithmetic overflow"),
        }
    }
}

/// Rounding direction of a division.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Rounding {
    /// Toward zero (floor, all operands are unsigned).
    Down,
    /// Away from zero (ceiling).
    Up,
}

/// `floor(a * b / c)` with a 256-bit intermediate.
pub fn mul_div_floor(a: u128, b: u128, c: u128) -> Result<u128, MathError> {
    mul_div(a, b, c, Rounding::Down)
}

/// `ceil(a * b / c)` with a 256-bit intermediate.
pub fn mul_div_ceil(a: u128, b: u128, c: u128) -> Result<u128, MathError> {
    mul_div(a, b, c, Rounding::Up)
}

/// `a * b / c` rounded in the given direction, with a 256-bit intermediate.
pub fn mul_div(a: u128, b: u128, c: u128, rounding: Rounding) -> Result<u128, MathError> {
    if c == 0 {
        return Err(MathError::DivisionByZero);
    }
    let (quotient, remainder) = (U256::from(a) * U256::from(b)).div_mod(U256::from(c));
    let quotient = if rounding == Rounding::Up && !remainder.is_zero() {
        quotient + 1
    } else {
        quotient
    };
    u256_to_u128(quotient)
}

/// `(floor(a * b / c), (a * b) mod c)` with a 256-bit intermediate.
pub fn mul_div_rem(a: u128, b: u128, c: u128) -> Result<(u128, u128), MathError> {
    if c == 0 {
        return Err(MathError::DivisionByZero);
    }
    let (quotient, remainder) = (U256::from(a) * U256::from(b)).div_mod(U256::from(c));
    Ok((u256_to_u128(quotient)?, remainder.low_u128()))
}

/// `product(factors) / product(divisors)` rounded in the given direction, with a 512-bit
/// intermediate. Up to three full-width factors always fit; an empty list is the product `1`.
pub fn mul_div_wide(
    factors: &[u128],
    divisors: &[u128],
    rounding: Rounding,
) -> Result<u128, MathError> {
    let numerator = product(factors)?;
    let denominator = product(divisors)?;
    if denominator.is_zero() {
        return Err(MathError::DivisionByZero);
    }
    let (quotient, remainder) = numerator.div_mod(denominator);
    let quotient = if rounding == Rounding::Up && !remainder.is_zero() {
        quotient + 1
    } else {
        quotient
    };
    if quotient > U512::from(u128::MAX) {
        return Err(MathError::Overflow);
    }
    Ok(quotient.low_u128())
}

/// `10^exponent`, checked.
pub fn pow10(exponent: u8) -> Result<u128, MathError> {
    10u128
        .checked_pow(u32::from(exponent))
        .ok_or(MathError::Overflow)
}

fn product(values: &[u128]) -> Result<U512, MathError> {
    values.iter().try_fold(U512::one(), |acc, &value| {
        acc.checked_mul(U512::from(value))
            .ok_or(MathError::Overflow)
    })
}

fn u256_to_u128(value: U256) -> Result<u128, MathError> {
    if value > U256::from(u128::MAX) {
        Err(MathError::Overflow)
    } else {
        Ok(value.low_u128())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn floor_and_ceil_round_in_opposite_directions() {
        assert_eq!(mul_div_floor(7, 3, 2), Ok(10));
        assert_eq!(mul_div_ceil(7, 3, 2), Ok(11));
        assert_eq!(mul_div_floor(6, 3, 2), Ok(9));
        assert_eq!(mul_div_ceil(6, 3, 2), Ok(9));
    }

    #[test]
    fn full_width_products_do_not_overflow() {
        assert_eq!(
            mul_div_floor(u128::MAX, u128::MAX, u128::MAX),
            Ok(u128::MAX)
        );
        assert_eq!(mul_div_ceil(u128::MAX, ONE, ONE), Ok(u128::MAX));
        assert_eq!(
            mul_div_wide(
                &[u128::MAX, u128::MAX, 3],
                &[u128::MAX, u128::MAX],
                Rounding::Down
            ),
            Ok(3)
        );
    }

    #[test]
    fn errors_are_returned_not_raised() {
        assert_eq!(mul_div_floor(1, 1, 0), Err(MathError::DivisionByZero));
        assert_eq!(mul_div_floor(u128::MAX, 2, 1), Err(MathError::Overflow));
        assert_eq!(
            mul_div_wide(&[u128::MAX; 5], &[1], Rounding::Down),
            Err(MathError::Overflow)
        );
        assert_eq!(
            mul_div_wide(&[1], &[0], Rounding::Up),
            Err(MathError::DivisionByZero)
        );
        assert_eq!(mul_div_rem(1, 1, 0), Err(MathError::DivisionByZero));
        assert_eq!(pow10(39), Err(MathError::Overflow));
    }

    #[test]
    fn remainder_matches_definition() {
        assert_eq!(mul_div_rem(10, 7, 4), Ok((17, 2)));
        assert_eq!(mul_div_rem(u128::MAX, 2, u128::MAX), Ok((2, 0)));
    }

    #[test]
    fn powers_of_ten() {
        assert_eq!(pow10(0), Ok(1));
        assert_eq!(pow10(6), Ok(1_000_000));
        assert_eq!(pow10(18), Ok(ONE));
        assert!(pow10(38).is_ok());
    }
}
